// Independent work: Implementing a complex algorithm alone
public class PaymentProcessor {
    // Deep focus needed: hold entire state machine in head
    public PaymentResult processPayment(PaymentRequest request) {
        var validation = validateRequest(request);
        if (!validation.isValid()) {
            return PaymentResult.rejected(validation.errors());
        }

        var authorization = authorizeWithBank(request);
        if (authorization.failed()) {
            return PaymentResult.failed(authorization.reason());
        }

        var transaction = recordTransaction(authorization);
        notifyCustomer(transaction);

        return PaymentResult.success(transaction.id());
    }
}

