@Service
public class OrderService {
    private List<Order> orderCache = new ArrayList<>(); // Not thread-safe!

    public void addOrder(Order order) {
        orderCache.add(order); // Multiple threads can corrupt this
    }

    public List<Order> getOrders() {
        return orderCache; // Returns mutable reference
    }
}

// How you helped in code review comment:
// "Hey, I noticed the orderCache field might have thread-safety issues
// because Spring services are singletons shared across requests.
// If two HTTP requests call addOrder() simultaneously, the ArrayList
// can get corrupted. Here's how I'd fix it:"

@Service
public class OrderService {
    private final List<Order> orderCache = 
        Collections.synchronizedList(new ArrayList<>());

    public void addOrder(Order order) {
        orderCache.add(order);
    }

    public List<Order> getOrders() {
        return List.copyOf(orderCache); // Return immutable copy
    }
}

