// Original estimate: 2 days for user registration feature
@RestController
public class UserController {
    @PostMapping("/register")
    public ResponseEntity<User> register(@RequestBody UserRequest request) {
        // Looked simple in planning:
        var user = userService.createUser(request);
        return ResponseEntity.ok(user);
    }
}

// What I discovered during implementation that broke the estimate:
// 1. Password hashing was not trivial (bcrypt setup)
// 2. Email validation needed regex pattern that I debugged for hours
// 3. Database unique constraint violations needed proper error handling
// 4. Integration tests required test containers setup I'd never done

@Service
public class UserService {
    private final PasswordEncoder encoder; // Needed to learn bcrypt
    private final EmailValidator validator; // Took time to get regex right

    @Transactional
    public User createUser(UserRequest request) {
        if (!validator.isValid(request.email())) {
            throw new ValidationException("Invalid email format");
        }

        try {
            var hashedPassword = encoder.encode(request.password());
            return userRepository.save(new User(request.email(), hashedPassword));
        } catch (DataIntegrityViolationException e) {
            throw new UserAlreadyExistsException(request.email());
        }
    }
}

